const incoming = $('Split Campaign Webhook').first().json;
const payload = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const leadList = $input.first().json;
const read = (source, name) => source?.[name] ?? source?.fields?.[name];
const numeric = (value, fallback = 0) => {
  if (Array.isArray(value)) value = value[0];
  if (value && typeof value === 'object') value = value.name ?? value.value;
  if (value === null || value === undefined || value === '') return fallback;
  const result = Number(value);
  return Number.isFinite(result) ? result : fallback;
};
const name = String(payload.Name || payload['Campaign Name'] || '').trim();
const genericLeadCount = Math.max(0, numeric(read(leadList, 'Final Generic Count')));
const directLeadCount = Math.max(0, numeric(read(leadList, 'Final Direct Count')));
let outputType;
if (/ - Generic Emails$/i.test(name)) outputType = 'generic';
else if (/ - Direct Emails$/i.test(name)) outputType = 'direct';
else if (genericLeadCount > 0 && directLeadCount === 0) outputType = 'generic';
else if (directLeadCount > 0 && genericLeadCount === 0) outputType = 'direct';
else throw new Error('Upload the existing Direct Emails or Generic Emails campaign. Splitting is handled in Campaign Center.');
const branchLeadCount = outputType === 'generic' ? genericLeadCount : directLeadCount;
if (!branchLeadCount) throw new Error('The selected output has no final leads.');
const rawAccounts = payload['Email Accounts'];
if (!Array.isArray(rawAccounts)) throw new Error('Select sender accounts before uploading.');
const accountIds = rawAccounts.map(value => typeof value === 'object' ? value.id : value);
if (!accountIds.length || accountIds.some(id => typeof id !== 'string' || !/^rec[a-zA-Z0-9]{14}$/.test(id))) throw new Error('Valid sender account links are required.');
if (new Set(accountIds).size !== accountIds.length) throw new Error('Duplicate sender account links must be resolved before uploading.');
const delayDays = Math.max(1, numeric(payload['Days Between Emails'], 1));
const senderDailyLimit = Math.max(1, numeric(payload['Sender Daily Limit'] ?? payload.senderDailyLimit, 15));
const maximumSenders = Math.max(1, Math.ceil(branchLeadCount / delayDays / senderDailyLimit));
if (accountIds.length > maximumSenders) throw new Error(outputType + ' has ' + accountIds.length + ' senders, above the maximum of ' + maximumSenders + ' for ' + branchLeadCount + ' leads. Reduce the selection before uploading.');
const existingId = numeric(payload.ID) || numeric(payload[outputType === 'generic' ? 'EmailBison Generic Campaign ID' : 'EmailBison Direct Campaign ID']);
if (existingId > 0) throw new Error('This campaign already has EmailBison ID ' + existingId + '. No duplicate was requested.');
// Forward exactly one existing campaign, retaining its name and every sender.
// This endpoint builds EmailBison drafts; it must not start LinkedIn campaigns.
return [{json: {...payload, Name: name, outputType, branchLeadCount,
  genericLeadCount, directLeadCount, senderDailyLimit, maximumSenders,
  'Email Accounts': rawAccounts, 'LinkedIn (from Client)': false,
  forceCreate: false, ID: null}}];

const incoming=$input.first().json;
const payload=incoming.body && typeof incoming.body==='object' ? incoming.body : incoming;
const recordId=String(payload.recordId || payload['Record ID'] || payload['Airtable Record ID'] || '').trim();
if (!/^rec[a-zA-Z0-9]{14}$/.test(recordId)) throw new Error('Cannot track campaign creation: a valid campaign recordId is required.');
return [{json:{recordId,runId:String($execution.id),startedAt:new Date().toISOString(),incoming}}];
